19	impl<T: HttpTransport, A: AuthProvider> CompactClient<T, A> {
20	    pub fn new(transport: T, provider: Provider, auth: A) -> Self {
21	        Self {
22	            session: EndpointSession::new(transport, provider, auth),
23	        }
24	    }
25	
26	    pub fn with_telemetry(self, request: Option<Arc<dyn RequestTelemetry>>) -> Self {
27	        Self {
28	            session: self.session.with_request_telemetry(request),
29	        }
30	    }
31	
32	    fn path() -> &'static str {
33	        "responses/compact"
34	    }
35	
36	    pub async fn compact(
37	        &self,
38	        body: serde_json::Value,
39	        extra_headers: HeaderMap,
40	    ) -> Result<Vec<ResponseItem>, ApiError> {
41	        let resp = self
42	            .session
43	            .execute(Method::POST, Self::path(), extra_headers, Some(body))
44	            .await?;
45	        let parsed: CompactHistoryResponse =
46	            serde_json::from_slice(&resp.body).map_err(|e| ApiError::Stream(e.to_string()))?;
47	        Ok(parsed.output)
48	    }
49	
50	    pub async fn compact_input(
51	        &self,
52	        input: &CompactionInput<'_>,
53	        extra_headers: HeaderMap,
54	    ) -> Result<Vec<ResponseItem>, ApiError> {
55	        let body = to_value(input)
56	            .map_err(|e| ApiError::Stream(format!("failed to encode compaction input: {e}")))?;
57	        self.compact(body, extra_headers).await
58	    }
59	}
