34	pub(crate) async fn run_remote_compact_task(
35	    sess: Arc<Session>,
36	    turn_context: Arc<TurnContext>,
37	) -> CodexResult<()> {
38	    let start_event = EventMsg::TurnStarted(TurnStartedEvent {
39	        turn_id: turn_context.sub_id.clone(),
40	        model_context_window: turn_context.model_context_window(),
41	        collaboration_mode_kind: turn_context.collaboration_mode.mode,
42	    });
43	    sess.send_event(&turn_context, start_event).await;
44	
45	    run_remote_compact_task_inner(&sess, &turn_context, InitialContextInjection::DoNotInject).await
46	}
