48	async fn run_remote_compact_task_inner(
49	    sess: &Arc<Session>,
50	    turn_context: &Arc<TurnContext>,
51	    initial_context_injection: InitialContextInjection,
52	) -> CodexResult<()> {
53	    if let Err(err) =
54	        run_remote_compact_task_inner_impl(sess, turn_context, initial_context_injection).await
55	    {
56	        let event = EventMsg::Error(
57	            err.to_error_event(Some("Error running remote compact task".to_string())),
58	        );
59	        sess.send_event(turn_context, event).await;
60	        return Err(err);
61	    }
62	    Ok(())
63	}
