153	pub(crate) async fn process_compacted_history(
154	    sess: &Session,
155	    turn_context: &TurnContext,
156	    mut compacted_history: Vec<ResponseItem>,
157	    initial_context_injection: InitialContextInjection,
158	) -> Vec<ResponseItem> {
159	    // Mid-turn compaction is the only path that must inject initial context above the last user
160	    // message in the replacement history. Pre-turn compaction instead injects context after the
161	    // compaction item, but mid-turn compaction keeps the compaction item last for model training.
162	    let initial_context = if matches!(
163	        initial_context_injection,
164	        InitialContextInjection::BeforeLastUserMessage
165	    ) {
166	        sess.build_initial_context(turn_context).await
167	    } else {
168	        Vec::new()
169	    };
170	
171	    compacted_history.retain(should_keep_compacted_history_item);
172	    insert_initial_context_before_last_real_user_or_summary(compacted_history, initial_context)
173	}
