185	///
186	/// This intentionally keeps:
187	/// - `assistant` messages (future remote compaction models may emit them)
188	/// - `user`-role warnings and compaction-generated summary messages because
189	///   they parse as `TurnItem::UserMessage`.
190	fn should_keep_compacted_history_item(item: &ResponseItem) -> bool {
191	    match item {
