218	        conversation_id: ThreadId,
219	        provider: ModelProviderInfo,
220	        session_source: SessionSource,
221	        model_verbosity: Option<VerbosityConfig>,
222	        responses_websockets_enabled_by_feature: bool,
223	        enable_request_compression: bool,
224	        include_timing_metrics: bool,
