244	    /// Creates a fresh turn-scoped streaming session.
245	    ///
246	    /// This constructor does not perform network I/O itself; the session opens a websocket lazily
247	    /// when the first stream request is issued.
248	    pub fn new_session(&self) -> ModelClientSession {
249	        ModelClientSession {
250	            client: self.clone(),
251	            websocket_session: self.take_cached_websocket_session(),
252	            turn_state: Arc::new(OnceLock::new()),
253	        }
