256	    fn take_cached_websocket_session(&self) -> WebsocketSession {
257	        let mut cached_websocket_session = self
258	            .state
259	            .cached_websocket_session
260	            .lock()
261	            .unwrap_or_else(std::sync::PoisonError::into_inner);
262	        std::mem::take(&mut *cached_websocket_session)
263	    }
264	
265	    fn store_cached_websocket_session(&self, websocket_session: WebsocketSession) {
266	        *self
267	            .state
268	            .cached_websocket_session
269	            .lock()
270	            .unwrap_or_else(std::sync::PoisonError::into_inner) = websocket_session;
271	    }
