273	    /// Compacts the current conversation history using the Compact endpoint.
274	    ///
275	    /// This is a unary call (no streaming) that returns a new list of
276	    /// `ResponseItem`s representing the compacted transcript.
277	    ///
278	    /// The model selection and telemetry context are passed explicitly to keep `ModelClient`
279	    /// session-scoped.
280	    pub async fn compact_conversation_history(
281	        &self,
282	        prompt: &Prompt,
283	        model_info: &ModelInfo,
284	        session_telemetry: &SessionTelemetry,
285	    ) -> Result<Vec<ResponseItem>> {
286	        if prompt.input.is_empty() {
287	            return Ok(Vec::new());
288	        }
289	        let client_setup = self.current_client_setup().await?;
290	        let transport = ReqwestTransport::new(build_reqwest_client());
291	        let request_telemetry = Self::build_request_telemetry(session_telemetry);
292	        let client =
293	            ApiCompactClient::new(transport, client_setup.api_provider, client_setup.api_auth)
294	                .with_telemetry(Some(request_telemetry));
295	
296	        let instructions = prompt.base_instructions.text.clone();
297	        let payload = ApiCompactionInput {
298	            model: &model_info.slug,
299	            input: &prompt.input,
300	            instructions: &instructions,
301	        };
302	
303	        let mut extra_headers = self.build_subagent_headers();
304	        extra_headers.extend(build_conversation_headers(Some(
305	            self.state.conversation_id.to_string(),
306	        )));
307	        client
308	            .compact_input(&payload, extra_headers)
309	            .await
310	            .map_err(map_api_error)
311	    }
