585	    fn get_incremental_items(
586	        &self,
587	        request: &ResponsesApiRequest,
588	        last_response: Option<&LastResponse>,
589	        allow_empty_delta: bool,
590	    ) -> Option<Vec<ResponseItem>> {
591	        // Checks whether the current request is an incremental extension of the previous request.
592	        // We only reuse an incremental input delta when non-input request fields are unchanged and
593	        // `input` is a strict
594	        // extension of the previous known input. Server-returned output items are treated as part
595	        // of the baseline so we do not resend them.
596	        let previous_request = self.websocket_session.last_request.as_ref()?;
597	        let mut previous_without_input = previous_request.clone();
598	        previous_without_input.input.clear();
599	        let mut request_without_input = request.clone();
600	        request_without_input.input.clear();
601	        if previous_without_input != request_without_input {
602	            trace!(
603	                "incremental request failed, properties didn't match {previous_without_input:?} != {request_without_input:?}"
604	            );
605	            return None;
606	        }
607	
608	        let mut baseline = previous_request.input.clone();
609	        if let Some(last_response) = last_response {
610	            baseline.extend(last_response.items_added.clone());
611	        }
612	
613	        let baseline_len = baseline.len();
614	        if request.input.starts_with(&baseline)
615	            && (allow_empty_delta || baseline_len < request.input.len())
616	        {
617	            Some(request.input[baseline_len..].to_vec())
618	        } else {
619	            trace!("incremental request failed, items didn't match");
620	            None
621	        }
622	    }
